local item_lib = require("items")
local phase = "ready"
local arrived = false
local delay_elapsed = false
local function transform(e)
  if phase ~= "escaping" or not arrived or not delay_elapsed then return end
  phase = "ended"; eq.stop_timer("escape")
  eq.unique_spawn(116574, 0, 0, 3419.4, -1739.7, 143.9, 383)
  eq.depop_with_timer()
end
function event_say(e)
  if e.message:findi("hail") then e.self:Say("Oh, I uh... err, hello there. Umm, thank Brelll you're here, those bloody Kromrif were going to torture me! Yes, yes, and you've saved me! How can I ever repay you?")
  elseif e.message:findi("murdrick") then e.self:Emote("looks away and stammers, Ehh, ahh, Mur who?")
  elseif e.message:findi("berradin") then e.self:Emote("goes even paler than usual, Hmm, Berradin you say? Sorry, but I've never even heard the name.") end
end
function event_trade(e)
  local camp = eq.get_entity_list():GetMobByNpcTypeID(116574)
  local hut_guard = eq.get_entity_list():GetMobByNpcTypeID(116182)
  local camp_guard = eq.get_entity_list():GetMobByNpcTypeID(2000951)
  if phase == "ready" and not camp.valid and not hut_guard.valid and not camp_guard.valid and
      item_lib.check_turn_in(e.trade, {item1 = 18171}) then
    phase = "escaping"
    eq.spawn2(116182, 0, 0, 3364, -1579, 163.8, 71.6)
    eq.spawn2(116182, 0, 0, 3314, -1557, 163.8, 84.8)
    eq.spawn2(116182, 0, 0, 3355, -1625, 163.8, 73.8)
    -- The timer is a minimum delay, never a substitute for actual movement.
    e.self:SetRunning(true)
    e.self:MoveTo(3303, -1623, 163.3)
    eq.set_timer("escape", 10000)
  end
  item_lib.return_items(e.self, e.other, e.trade)
end
function event_waypoint_depart(e)
  if phase == "escaping" then arrived = true; transform(e) end
end
function event_timer(e)
  if e.timer == "escape" and phase == "escaping" then
    delay_elapsed = true; eq.stop_timer("escape"); transform(e)
  end
end
function event_death_complete(e)
  phase = "ended"; eq.stop_timer("escape")
  -- A failed escape must not leave orphaned event guards indefinitely.
  eq.depop_all(116182); eq.depop_all(2000951)
end
